// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != c.owner());

        vm.deal(address(c), amount);

        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, amount));

        assertTrue(!success);
    }
}
